#define RESIDUAL_HIER_VO_NO_MAIN
#include "residual_hier_vo.cpp"
#undef RESIDUAL_HIER_VO_NO_MAIN

// Approximate authenticated routing with an implicit balanced binary tree.
// Every internal record contains one representative PQ code; leaf records
// contain fine residual codes.  Child positions follow the canonical balanced
// preorder topology, so no adjacency ids are transmitted.

struct PSTNode {int pivot=-1,left=-1,right=-1,leaf=-1;float radius=0;};
struct PSTree {std::vector<PSTNode>nodes;std::vector<int>leaf_order;};

static int pst_build_node(PSTree&tree,const Matrix&decoded,std::vector<int>ids,int iters){
    int here=tree.nodes.size();tree.nodes.push_back({});std::vector<double>mean(decoded.d);for(int id:ids)for(int j=0;j<decoded.d;++j)mean[j]+=decoded[id][j];for(double&x:mean)x/=ids.size();double best=std::numeric_limits<double>::infinity();
    for(int id:ids){double z=0;for(int j=0;j<decoded.d;++j){double x=decoded[id][j]-mean[j];z+=x*x;}if(z<best){best=z;tree.nodes[here].pivot=id;}}
    double radius2=0;for(int id:ids)radius2=std::max(radius2,(double)l2(decoded[id],decoded[tree.nodes[here].pivot],decoded.d));double radius=std::sqrt(radius2);tree.nodes[here].radius=(float)radius;if((double)tree.nodes[here].radius<radius)tree.nodes[here].radius=std::nextafter(tree.nodes[here].radius,std::numeric_limits<float>::infinity());
    if(ids.size()==1){tree.nodes[here].leaf=ids[0];tree.leaf_order.push_back(ids[0]);return here;}
    int a=ids[0],b=a;float far=-1;for(int id:ids){float z=l2(decoded[a],decoded[id],decoded.d);if(z>far){far=z;b=id;}}std::vector<float>ca(decoded[a],decoded[a]+decoded.d),cb(decoded[b],decoded[b]+decoded.d);std::vector<std::pair<float,int>>rank(ids.size());
    for(int it=0;it<std::max(1,iters);++it){for(size_t z=0;z<ids.size();++z)rank[z]={l2(decoded[ids[z]],ca.data(),decoded.d)-l2(decoded[ids[z]],cb.data(),decoded.d),ids[z]};std::sort(rank.begin(),rank.end(),[](const auto&x,const auto&y){return x.first==y.first?x.second<y.second:x.first<y.first;});std::fill(ca.begin(),ca.end(),0);std::fill(cb.begin(),cb.end(),0);int cut=ids.size()/2;
        for(int z=0;z<(int)rank.size();++z){auto&c=z<cut?ca:cb;for(int j=0;j<decoded.d;++j)c[j]+=decoded[rank[z].second][j];}for(float&x:ca)x/=cut;for(float&x:cb)x/=(rank.size()-cut);}
    int cut=ids.size()/2;std::vector<int>left,right;for(int z=0;z<(int)rank.size();++z)(z<cut?left:right).push_back(rank[z].second);tree.nodes[here].left=pst_build_node(tree,decoded,std::move(left),iters);tree.nodes[here].right=pst_build_node(tree,decoded,std::move(right),iters);return here;
}

static std::vector<PSTree> pst_build(const std::vector<std::vector<int>>&groups,const Matrix&decoded,int iters){std::vector<PSTree>out(groups.size());for(size_t g=0;g<groups.size();++g)pst_build_node(out[g],decoded,groups[g],iters);return out;}

struct PSTOpen {int group=0;std::vector<int>positions;};
struct PSTRun {std::vector<VLState>state;std::vector<std::vector<int>>coarse;std::vector<std::vector<PSTOpen>>opened;double recall=0,query_ms=0,records=0,internal_expanded=0,leaf_candidates=0,record_bytes=0;uint64_t selection_mismatches=0;};
struct PSTItem {float distance=0;int group=0,node=0;};
struct PSTGreater {bool operator()(const PSTItem&a,const PSTItem&b)const{return a.distance==b.distance?(a.group==b.group?a.node>b.node:a.group>b.group):a.distance>b.distance;}};

static PSTRun pst_query(const Matrix&xb,const Matrix&q,const std::vector<std::vector<int>>&lists,const std::vector<std::vector<int>>&groups,
        const Matrix&coarse_centers,const Matrix&residual,const CRCodec&coarse_codec,const CRCodec&residual_codec,const std::vector<PSTree>&tree,
        int coarse_probe,int fine_probe,int k,int leaf_budget,const RHStates&reference,const std::vector<std::vector<int>>&gt){
    PSTRun out;out.state.resize(q.rows());out.coarse.resize(q.rows());out.opened.resize(q.rows());uint64_t hits=0;double elapsed=0;
    for(size_t qi=0;qi<q.rows();++qi){auto begin=std::chrono::steady_clock::now();auto clut=coarse_codec.prepare(q[qi]);std::vector<int>corder(groups.size());std::iota(corder.begin(),corder.end(),0);std::partial_sort(corder.begin(),corder.begin()+coarse_probe,corder.end(),[&](int a,int b){float x=coarse_codec.distance(q[qi],clut,coarse_centers,a,false),y=coarse_codec.distance(q[qi],clut,coarse_centers,b,false);return x==y?a<b:x<y;});out.coarse[qi].assign(corder.begin(),corder.begin()+coarse_probe);
        std::vector<std::vector<float>>luts(groups.size());std::vector<std::vector<uint8_t>>seen(groups.size());std::vector<std::vector<int>>opened(groups.size());std::priority_queue<PSTItem,std::vector<PSTItem>,PSTGreater>frontier;std::vector<std::pair<float,int>>candidate;uint64_t bits=0;int records=0,expanded=0,internal_records=0;
        auto discover=[&](int g,int node){if(seen[g][node])return;seen[g][node]=1;int id=tree[g].nodes[node].pivot;float d=residual_codec.distance(nullptr,luts[g],residual,id,false);float key=d;if(tree[g].nodes[node].leaf<0){double x=std::max(0.0,std::sqrt(std::max(0.0,(double)d))-(double)tree[g].nodes[node].radius);key=std::nextafter((float)(x*x),-std::numeric_limits<float>::infinity());++internal_records;}frontier.push({key,g,node});opened[g].push_back(node);++records;std::vector<int>one{id};bits+=residual_codec.huffman_bit_count(one);};
        for(int z=0;z<coarse_probe;++z){int g=corder[z];auto dc=coarse_codec.decode(coarse_centers,g);std::vector<float>qr(q.d);for(int j=0;j<q.d;++j)qr[j]=q[qi][j]-dc[j];luts[g]=residual_codec.prepare(qr.data());seen[g].assign(tree[g].nodes.size(),0);discover(g,0);}
        while((int)candidate.size()<leaf_budget&&!frontier.empty()){auto x=frontier.top();frontier.pop();const auto&node=tree[x.group].nodes[x.node];if(node.leaf>=0){candidate.push_back({x.distance,node.leaf});continue;}++expanded;discover(x.group,node.left);discover(x.group,node.right);}
        if((int)candidate.size()<fine_probe)throw std::runtime_error("PQ search tree found too few leaves");std::partial_sort(candidate.begin(),candidate.begin()+fine_probe,candidate.end(),[](const auto&a,const auto&b){return a.first==b.first?a.second<b.second:a.first<b.first;});auto&s=out.state[qi];for(int z=0;z<fine_probe;++z)s.lists.push_back(candidate[z].second);auto got=s.lists,want=reference.state[qi].lists;std::sort(got.begin(),got.end());std::sort(want.begin(),want.end());if(got!=want)++out.selection_mismatches;
        std::priority_queue<std::pair<float,int>>objects;for(int c:s.lists)for(int id:lists[c]){float d=l2(q[qi],xb[id],xb.d);if((int)objects.size()<k)objects.push({d,id});else if(d<objects.top().first||(d==objects.top().first&&id<objects.top().second)){objects.pop();objects.push({d,id});}}if((int)objects.size()!=k)throw std::runtime_error("PQ search tree found too few objects");s.tau2=objects.top().first;while(!objects.empty()){s.answer.push_back(objects.top().second);objects.pop();}elapsed+=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();std::unordered_set<int>answer(s.answer.begin(),s.answer.end());for(int id:gt[qi])hits+=answer.count(id);
        out.records+=records;out.internal_expanded+=expanded;out.leaf_candidates+=candidate.size();out.record_bytes+=(bits+internal_records*32+7)/8.0;for(int g:out.coarse[qi])if(!opened[g].empty())out.opened[qi].push_back({g,std::move(opened[g])});}
    double nq=q.rows();out.recall=hits/(nq*k);out.query_ms=elapsed/nq;out.records/=nq;out.internal_expanded/=nq;out.leaf_candidates/=nq;out.record_bytes/=nq;return out;
}

struct PSTRoute {double parameters=0,models=0,coarse_codes=0,tree_codes=0,group_metadata=0,fine_metadata=0,coarse_proofs=0,tree_proofs=0,fine_proofs=0,total=0;};
static PSTRoute pst_route(const PSTRun&query,const std::vector<std::vector<int>>&groups,const std::vector<int>&group_of,const std::vector<int>&leaf_position,const std::vector<PSTree>&tree,const RHLayout&layout,const CRCodec&coarse_codec,const CRCodec&residual_codec){
    PSTRoute out;out.parameters=96.0+coarse_codec.parameter_bytes()+residual_codec.parameter_bytes()+4.0;out.models=coarse_codec.huffman_model_bytes()+residual_codec.huffman_model_bytes();std::vector<int>all(groups.size());std::iota(all.begin(),all.end(),0);out.coarse_codes=coarse_codec.huffman_bytes(all);out.tree_codes=query.record_bytes;std::vector<std::vector<int>>selected(groups.size());std::vector<int>mapped;
    for(size_t qi=0;qi<query.state.size();++qi){const auto&cg=query.coarse[qi];out.group_metadata+=cg.size()*70.0;mapped.clear();for(int g:cg)mapped.push_back(layout.coarse_position[g]);out.coarse_proofs+=hv_dummy_proof_count(groups.size(),mapped)*32.0;for(const auto&open:query.opened[qi])out.tree_proofs+=hv_dummy_proof_count(tree[open.group].nodes.size(),open.positions)*32.0;for(auto&v:selected)v.clear();for(int leaf:query.state[qi].lists)selected[group_of[leaf]].push_back(leaf_position[leaf]);for(int g:cg)if(!selected[g].empty()){out.fine_metadata+=selected[g].size()*4.0;out.fine_proofs+=hv_dummy_proof_count(groups[g].size(),selected[g])*32.0;}}
    double nq=query.state.size();out.group_metadata/=nq;out.fine_metadata/=nq;out.coarse_proofs/=nq;out.tree_proofs/=nq;out.fine_proofs/=nq;out.total=out.parameters+out.models+out.coarse_codes+out.tree_codes+out.group_metadata+out.fine_metadata+out.coarse_proofs+out.tree_proofs+out.fine_proofs+16.0;return out;
}

int main(int argc,char**argv)try{
    auto cfg=cr_args(argc,argv);if(!cfg.coarse_nlist||cfg.coarse_codec.empty()||cfg.residual_codec.empty())throw std::runtime_error("require coarse options plus both codecs");std::cerr<<"Loading/training index...\n";Matrix xb=fvecs(cfg.data+"/sift_base.fvecs",cfg.base),trainq=fvecs(cfg.data+"/sift_learn.fvecs",cfg.train_queries),testq=fvecs(cfg.data+"/sift_query.fvecs",cfg.test_queries);auto lists=hkmeans(xb,cfg.nlist,cfg.iters);auto fine_vector=centers(xb,lists);Matrix fine_centers=cr_matrix(fine_vector);auto groups=hkmeans(fine_centers,cfg.coarse_nlist,cfg.iters);Matrix coarse_centers=cr_matrix(centers(fine_centers,groups));std::vector<int>group_of(cfg.nlist,-1),position(cfg.nlist,-1);for(size_t g=0;g<groups.size();++g)for(size_t p=0;p<groups[g].size();++p){group_of[groups[g][p]]=g;position[groups[g][p]]=p;}
    Matrix residual;residual.d=xb.d;residual.x.resize((size_t)cfg.nlist*xb.d);for(int leaf=0;leaf<cfg.nlist;++leaf)for(int j=0;j<xb.d;++j)residual.x[(size_t)leaf*xb.d+j]=fine_centers[leaf][j]-coarse_centers[group_of[leaf]][j];Matrix empty;CRCodec coarse_codec(cfg.coarse_codec,coarse_centers,empty,std::min(cfg.pq_train,cfg.coarse_nlist),cfg.pq_iters,cfg.seed),residual_codec(cfg.residual_codec,residual,empty,cfg.pq_train,cfg.pq_iters,cfg.seed+1);auto gt=exact_gt(xb,testq,cfg.k);auto train=rh_states(xb,trainq,lists,fine_centers,groups,group_of,coarse_centers,residual,coarse_codec,residual_codec,cfg.coarse_nprobe,cfg.nprobe,cfg.k,nullptr),test=rh_states(xb,testq,lists,fine_centers,groups,group_of,coarse_centers,residual,coarse_codec,residual_codec,cfg.coarse_nprobe,cfg.nprobe,cfg.k,&gt);
    auto boundaries=verification_tree_bounds(xb,trainq,lists,train.state,0,cfg.train_queries);NestedRule quantizer(xb,std::move(boundaries));if(!quantizer.contains(xb))throw std::runtime_error("quantizer containment failure");auto tail=hv_lossless_tail(xb,quantizer);HVLayout identity;identity.routing_position.resize(lists.size());std::iota(identity.routing_position.begin(),identity.routing_position.end(),0);int split=cfg.train_queries/2;auto order=hv_downgrade_order(xb,trainq,train.state,0,split,lists,quantizer);std::vector<int>counts{0,8,16,24,32,48,64,80,96,112,128};HVProtocol independent;independent.lossless_tail=true;independent.positional_ids=true;independent.public_dummy=true;int best_count=0;double best=std::numeric_limits<double>::infinity();for(int count:counts){auto b=hv_downgrade_bits(xb.d,order,count);auto e=hv_protocol_evaluate(xb,trainq,train.state,split,cfg.train_queries,lists,quantizer,b,identity,tail,independent,1,false);if(e.total-e.routing<best){best=e.total-e.routing;best_count=count;}}auto all_order=hv_downgrade_order(xb,trainq,train.state,0,cfg.train_queries,lists,quantizer);auto bits=hv_downgrade_bits(xb.d,all_order,best_count);auto ie=hv_protocol_evaluate(xb,trainq,train.state,0,cfg.train_queries,lists,quantizer,bits,identity,tail,independent,1,false);HVProtocol fused=independent;fused.fused_commitment=true;auto fe=hv_protocol_evaluate(xb,trainq,train.state,0,cfg.train_queries,lists,quantizer,bits,identity,tail,fused,1,false);const auto&protocol=(fe.total-fe.routing)<(ie.total-ie.routing)?fused:independent;auto be=hv_protocol_evaluate(xb,testq,test.state,0,cfg.test_queries,lists,quantizer,bits,identity,tail,protocol,cfg.repeats,true);double baseline_leaf=be.total-be.routing,leaf_parameters=cr_leaf_parameter_bytes(quantizer,bits);auto layout=rh_learn_layout(train,groups,group_of,position,cfg.seed);auto br=rh_route(test,groups,group_of,layout,coarse_codec,residual_codec);br.huffman_total+=leaf_parameters;double baseline_total=br.huffman_total+baseline_leaf;
    Matrix decoded;decoded.d=residual.d;decoded.x.resize(residual.x.size());for(size_t id=0;id<residual.rows();++id){auto v=residual_codec.decode(residual,id);std::copy(v.begin(),v.end(),decoded.x.begin()+id*(size_t)decoded.d);}std::cerr<<"Building implicit PQ search trees...\n";auto tree=pst_build(groups,decoded,std::min(3,cfg.iters));std::vector<int>leaf_position(cfg.nlist,-1);for(size_t g=0;g<tree.size();++g)for(size_t p=0;p<tree[g].leaf_order.size();++p)leaf_position[tree[g].leaf_order[p]]=p;std::vector<int>budgets=cfg.beam==0?std::vector<int>{800,1000,1200,1600,2000,2500,3000,4000,5000,7000}:std::vector<int>{cfg.beam};
    std::ofstream out(cfg.output);if(!out)throw std::runtime_error("cannot open output");out<<std::setprecision(12)<<"leaf_budget,recall,avg_tree_records,avg_internal_expanded,avg_leaf_candidates,routing_parameters,huffman_models,huffman_coarse_codes,huffman_tree_codes,group_metadata,fine_metadata,coarse_proofs,tree_proofs,fine_proofs,routing_total,leaf_total,total_vo,baseline_huffman_total,vo_reduction_vs_baseline,ann_query_ms,baseline_query_ms,violations\n";
    for(int budget:budgets){std::cerr<<"Query leaf budget="<<budget<<"...\n";auto run=pst_query(xb,testq,lists,groups,coarse_centers,residual,coarse_codec,residual_codec,tree,cfg.coarse_nprobe,cfg.nprobe,cfg.k,budget,test,gt);auto route=pst_route(run,groups,group_of,leaf_position,tree,layout,coarse_codec,residual_codec);route.parameters+=leaf_parameters;route.total+=leaf_parameters;auto le=hv_protocol_evaluate(xb,testq,run.state,0,cfg.test_queries,lists,quantizer,bits,identity,tail,protocol,cfg.repeats,true);double leaf_total=le.total-le.routing,total=route.total+leaf_total;uint64_t violations=le.object_violations+run.selection_mismatches;out<<budget<<','<<run.recall<<','<<run.records<<','<<run.internal_expanded<<','<<run.leaf_candidates<<','<<route.parameters<<','<<route.models<<','<<route.coarse_codes<<','<<route.tree_codes<<','<<route.group_metadata<<','<<route.fine_metadata<<','<<route.coarse_proofs<<','<<route.tree_proofs<<','<<route.fine_proofs<<','<<route.total<<','<<leaf_total<<','<<total<<','<<baseline_total<<','<<1-total/baseline_total<<','<<run.query_ms<<','<<test.query_ms<<','<<violations<<'\n';std::cout<<"budget="<<budget<<" recall="<<run.recall<<" records="<<run.records<<" route="<<route.total/1024<<" KiB total="<<total/1024<<" KiB reduction="<<(1-total/baseline_total)*100<<"% query="<<run.query_ms<<" ms mismatches="<<run.selection_mismatches<<" violations="<<violations<<'\n';}
    return 0;
}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
